WITH scored AS (SELECT *, CUME_DIST() OVER (ORDER BY credit_limit DESC NULLS FIRST) AS credit_limit_cume_dist, NTILE(4) OVER (PARTITION BY city ORDER BY credit_limit, id) AS credit_limit_bucket, LEAD(age, 2, 0) OVER w_ordered AS next_age, FIRST_VALUE(segment) IGNORE NULLS OVER (ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_segment, NTILE(5) OVER (PARTITION BY segment ORDER BY age DESC, id) AS age_bucket FROM customers WINDOW w_ordered AS (PARTITION BY country ORDER BY signup_date, id)) SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, CASE WHEN city RLIKE '^(Berlin|Singapore)$' THEN 'GROUP_B' ELSE 'EXTENDED' END AS city_zone FROM scored ORDER BY signup_date
